import * as dntShim from "../../../_dnt.shims.js";
import { withProjectSourceContext } from "../../shared/project-source-context.js";
import { discoverWebhooks } from "../../../src/webhook/index.js";
import { outputTriggerList } from "../trigger-utils.js";
function formatWebhook(webhook) {
    return `${webhook.id} -> ${webhook.target.kind}:${webhook.target.id}`;
}
export async function handleWebhooksCommand(_args) {
    const projectDir = dntShim.Deno.cwd();
    await withProjectSourceContext(projectDir, async ({ adapter, config }) => {
        const result = await discoverWebhooks({
            projectDir,
            adapter,
            config,
            allowHostProjectCodeExecution: true,
        });
        await outputTriggerList({
            command: "webhooks",
            items: result.items,
            errors: result.errors,
            formatItem: formatWebhook,
        });
    });
}
